struct usb_cdc_union_desc *get_cdc_union_desc(struct usb_interface *intf) {
    struct usb_host_interface *host_intf;
    struct usb_endpoint_descriptor *ep;
    struct usb_cdc_union_desc *desc;
    unsigned char *data;
    int i;

    host_intf = &intf->altsetting[0];
    data = host_intf->extra;
    if (!data) {
        dev_err(&intf->dev, "No extra descriptors found\n");
        return NULL;
    }

    for (i = 0; i < host_intf->extralen;) {
        desc = (struct usb_cdc_union_desc *)&data[i];
        if (desc->bLength != sizeof(*desc)) {
            dev_err(&intf->dev, "Invalid CDC union descriptor length\n");
            return NULL;
        }

        if (desc->bDescriptorType != USB_DT_CS_INTERFACE ||
            desc->bDescriptorSubtype != USB_CDC_SUBTYPE_UNION) {
            dev_err(&intf->dev, "Invalid CDC union descriptor type/subtype\n");
            return NULL;
        }

        return desc;
    }

    dev_err(&intf->dev, "CDC union descriptor not found\n");
    return NULL;
}

struct usb_cdc_union_desc *get_cdc_union_desc(struct usb_interface *intf)
{
    struct usb_descriptor_header **extra;
    unsigned char *p;
    int i, n;

    extra = intf->extra;
    if (!extra)
        return NULL;

    for (i = 0; i < intf->num_extra; i++) {
        if (extra[i]->bLength < sizeof(struct usb_cdc_union_desc))
            continue;
        if (extra[i]->bDescriptorType != USB_DT_CS_INTERFACE)
            continue;

        p = (unsigned char *)extra[i];
        n = p[1]; /* bLength is in byte 1 */
        if (n < sizeof(struct usb_cdc_union_desc))
            continue;

        if (p[2] != USB_CDC_UNION_TYPE) /* bDescriptorSubtype is in byte 2 */
            continue;

        return (struct usb_cdc_union_desc *)extra[i];
    }

    dev_dbg(&intf->dev, "CDC union descriptor not found\n");
    return NULL;
}

